struct smbd_server_connection {
	struct {
		bool got_session;
	} nbt;
	bool allow_smb2;
	struct {
		struct fd_event *fde;
		uint64_t num_requests;
		struct {
			bool encrypted_passwords;
			bool spnego;
			struct auth_context *auth_context;
			bool done;
			/*
			 * Size of the data we can receive. Set by us.
			 * Can be modified by the max xmit parameter.
			 */
			int max_recv;
		} negprot;

		struct {
			bool done_sesssetup;
			/*
			 * Size of data we can send to client. Set
			 *  by the client for all protocols above CORE.
			 *  Set by us for CORE protocol.
			 */
			int max_send;
			uint16_t last_session_tag;

			/* users from session setup */
			char *session_userlist;
			/* workgroup from session setup. */
			char *session_workgroup;
			/*
			 * this holds info on user ids that are already
			 * validated for this VC
			 */
			user_struct *validated_users;
			uint16_t next_vuid;
			int num_validated_vuids;
#ifdef HAVE_NETGROUP
			char *my_yp_domain;
#endif
		} sessions;
		struct {
			connection_struct *Connections;
			/* number of open connections */
			struct bitmap *bmap;
			int num_open;
		} tcons;
		struct smb_signing_state *signing_state;
		/* List to store partial SPNEGO auth fragments. */
		struct pending_auth_data *pd_list;

		struct notify_mid_map *notify_mid_maps;

		struct {
			struct bitmap *dptr_bmap;
			struct dptr_struct *dirptrs;
			int dirhandles_open;
		} searches;
	} smb1;
	struct {
		struct tevent_context *event_ctx;
		struct tevent_queue *recv_queue;
		struct tevent_queue *send_queue;
		struct tstream_context *stream;
		struct {
			/* an id tree used to allocate vuids */
			/* this holds info on session vuids that are already
			 * validated for this VC */
			struct idr_context *idtree;

			/* this is the limit of vuid values for this connection */
			uint64_t limit;

			struct smbd_smb2_session *list;
		} sessions;
		struct smbd_smb2_request *requests;
	} smb2;
}

struct smb_request {
	uint8_t cmd;
	uint16 flags2;
	uint16 smbpid;
	uint16 mid;
	uint32_t seqnum;
	uint16 vuid;
	uint16 tid;
	uint8  wct;
	uint16_t *vwv;
	uint16_t buflen;
	const uint8_t *buf;
	const uint8 *inbuf;

	/*
	 * Async handling in the main smb processing loop is directed by
	 * outbuf: reply_xxx routines indicate sync behaviour by putting their
	 * reply into "outbuf". If they leave it as NULL, they take of it
	 * themselves, possibly later.
	 *
	 * If async handling is wanted, the reply_xxx routine must make sure
	 * that it talloc_move()s the smb_req somewhere else.
	 */
	uint8 *outbuf;

	size_t unread_bytes;
	bool encrypted;
	connection_struct *conn;
	struct smb_perfcount_data pcd;

	/*
	 * Chained request handling
	 */
	struct files_struct *chain_fsp;

	/*
	 * Here we collect the outbufs from the chain handlers
	 */
	uint8_t *chain_outbuf;

	/*
	 * state information for async smb handling
	 */
	void *async_priv;

	bool done;
}

